// usage: node gq.mjs <store> <queryfile> [varsfile] [--allow-mutation]
import { execFileSync, spawnSync } from 'child_process';
import fs from 'fs';
const [store, qf, vf, flag] = process.argv.slice(2);
const q = fs.readFileSync(qf, 'utf8');
if (/\bmutation\b/.test(q) && flag !== '--allow-mutation') { console.error('REFUSING: mutation without --allow-mutation'); process.exit(3); }
const SAFE_STORE = 'ordermergetest2.myshopify.com';
if (/\bmutation\b/.test(q) && store !== SAFE_STORE) { console.error('REFUSING: mutations only on ' + SAFE_STORE); process.exit(3); }
const args = ['shopify','app','execute','--store',store,'--version','2026-04','--query-file',qf];
if (vf) args.push('--variable-file', vf);
if (/\bmutation\b/.test(q)) args.push('--allow-mutations');
const r = spawnSync('npx', args, { cwd: '<home>/Desktop/shopifymerger/order-merge-app', encoding: 'utf8', shell: true, maxBuffer: 64*1024*1024 });
const text = ((r.stdout||'') + '\n' + (r.stderr||'')).replace(/\x1b\[[0-9;]*[A-Za-z]/g, '');
const stripped = text.split('\n').map(l => { const m = l.match(/^\s*│\s?(.*?)\s*│?\s*$/); return m ? m[1] : l; }).join('\n');
const s = stripped.indexOf('{'), e = stripped.lastIndexOf('}');
let body = null; try { body = JSON.parse(stripped.slice(s, e+1)); } catch { }
console.log(JSON.stringify(body ?? { raw: stripped.slice(0, 3000) }, null, 1));

